local OverseaManageCafeCattyConditionCell = Class('OverseaManageCafeCattyConditionCell')
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule

function OverseaManageCafeCattyConditionCell:__init()
    
    self.vo = nil
end

function OverseaManageCafeCattyConditionCell:__delete()
    
    self.vo = nil
end

function OverseaManageCafeCattyConditionCell:Awake()
    self:AddUIClick()
end

function OverseaManageCafeCattyConditionCell:AddUIClick()
    SetButtonAction(self.FontStyleButton.gameObject,Bind(self,self.OnGoToBtnClick))
end

function OverseaManageCafeCattyConditionCell:SetConditionShow(vo,index,callBack)
    self.vo = vo
    self.callBack = callBack
    CfUtils.FillText(self.TxtTitle.gameObject,vo.desc1)
    local maidCoffeeComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local maidHomeDoJo = maidCoffeeComponent:GetMaidCoffeeHomeDoJo()
    local progress = maidHomeDoJo:GetTaskProgress(vo.refId)

    local isComplete = maidHomeDoJo:JudgeIsCompleteQuest(vo.refId,vo.taskContenNum)
    local color = isComplete and "<color=#5C5C5C>%s</color><color=#5C5C5C>/%s</color>" or "<color=#FF1BAF>%s</color><color=#A5A5A5>/%s</color>"
    CfUtils.FillText(self.TxtNum.gameObject,string.format(color,progress,vo.taskContenNum))
    KTool.SetActive(self.FontStyleButton,not isComplete)
    KTool.SetActive(self.IconNode.gameObject,isComplete)

    --self.ImgReach.Status = isComplete and 1 or 2
    --self.TxtTitle.Status = isComplete and 1 or 2
    --self.TxtNum.Status = isComplete and 1 or 2
end

function OverseaManageCafeCattyConditionCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

function OverseaManageCafeCattyConditionCell:OnGoToBtnClick()
    local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
    if self.vo.type == 1 then
        local MaidCoffeeMgr = import('Game.MaidCoffee.MaidCoffeeMgr')
        local tabIndex,id = MaidCoffeeMgr:GetInstance():GetCanGetRecipeInfo()
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeeCookingMainDialog, parameters = { type = MaidCoffeeConstants.CookingType.Cooking,tableIndex = tabIndex,id = id ,cb = function()
            if self.callBack then
                --self.callBack()
            end
        end} },{{id = Constants.UITypeIds.UIMaidCoffeeCattyMain}})
    elseif self.vo.type == 2 then
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIMaidCoffeeCookingMainDialog, parameters = { type = MaidCoffeeConstants.CookingType.Cooking,tableIndex = 1,cb = function()
            if self.callBack then
                --self.callBack()
            end
        end } },{{id = Constants.UITypeIds.UIMaidCoffeeCattyMain}})
    else
        local row = GoodsConfMgr:GetInstance():GetJumpModuleRow(self.vo.type)
        GoodsConfMgr:GetInstance():ExecuteJump(row, {})
    end
end

return OverseaManageCafeCattyConditionCell